create type public.app_role as enum ('admin','advisor');
create type public.property_status as enum ('draft','active','reserved','sold','rented','inactive');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.app_role not null default 'advisor', active boolean not null default true, created_at timestamptz not null default now());
create table public.properties(id uuid primary key default gen_random_uuid(), owner_user_id uuid not null references public.profiles(id), title text not null, address text, zone text, property_type text, price numeric, bedrooms int, bathrooms int, area_m2 numeric, status public.property_status not null default 'draft', shared boolean not null default true, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.clients(id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.profiles(id), name text not null, phone text, email text, client_type text, zone text, budget_max numeric, bedrooms_min int, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.profiles(id), client_id uuid references public.clients(id) on delete set null, zone text, budget_max numeric, bedrooms_min int, property_type text, features text, status text not null default 'active', created_at timestamptz not null default now());
create table public.acquisitions(id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.profiles(id), owner_name text, phone text, address text, zone text, property_type text, estimated_price numeric, status text not null default 'new', next_contact_at timestamptz, notes text, created_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.profiles(id), title text not null, starts_at timestamptz not null, ends_at timestamptz, kind text, related_type text, related_id uuid, notes text);
create table public.news(id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), title text not null, body text not null, published boolean not null default true, created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and active=true); $$;
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.clients enable row level security; alter table public.orders enable row level security; alter table public.acquisitions enable row level security; alter table public.events enable row level security; alter table public.news enable row level security;
create policy "profiles own or admin" on public.profiles for select using (id=auth.uid() or public.is_admin());
create policy "properties read shared or own" on public.properties for select using (public.is_admin() or owner_user_id=auth.uid() or shared=true);
create policy "properties insert own" on public.properties for insert with check (owner_user_id=auth.uid() or public.is_admin());
create policy "properties update own/admin" on public.properties for update using (owner_user_id=auth.uid() or public.is_admin());
create policy "properties delete own/admin" on public.properties for delete using (owner_user_id=auth.uid() or public.is_admin());
create policy "clients own/admin" on public.clients for all using (advisor_id=auth.uid() or public.is_admin()) with check (advisor_id=auth.uid() or public.is_admin());
create policy "orders own/admin" on public.orders for all using (advisor_id=auth.uid() or public.is_admin()) with check (advisor_id=auth.uid() or public.is_admin());
create policy "acquisitions own/admin" on public.acquisitions for all using (advisor_id=auth.uid() or public.is_admin()) with check (advisor_id=auth.uid() or public.is_admin());
create policy "events own/admin" on public.events for all using (advisor_id=auth.uid() or public.is_admin()) with check (advisor_id=auth.uid() or public.is_admin());
create policy "news read authenticated" on public.news for select using (auth.uid() is not null); create policy "news admin write" on public.news for all using (public.is_admin()) with check (public.is_admin());
